	[1412] = {
		name = "Мулгор",
		short = "Сотни лет у тауренов не было своей земли: кентавры-налётчики гоняли их по всему Калимдору, рассеивая племена по кочевым стойбищам.",
		full = "Сотни лет у тауренов не было своей земли: кентавры-налётчики гоняли их по всему Калимдору, рассеивая племена по кочевым стойбищам. Когда Тралл и его орки высадились на эти берега, Кэрн Кровавое Копыто увидел в них родственные души, благородные и сильные. Под охраной орков и опираясь на их мощь, Кэрн привёл свой народ в укрытую долину, со всех сторон окружённую горами, и там его племя Кровавого Копыта прогнало кентавров с лугов и наконец обрело их.\n\nНа плато, возвышавшемся над равниной, Кэрн построил Громовой Утес — убежище, открытое для тауренов любого племени, и со временем рассеянные народы объединились под его властью.\n\nПастбища по-прежнему зелены, плато всё так же отбрасывают длинные тени на Деревню Кровавого Копыта, и каждый таурен, достигший зрелости, как и его предки, должен уйти в дикие равнины, чтобы проявить себя на Великой Охоте.",
