	[1413] = {
		name = "Степи",
		short = "Пыль здесь не всегда была пылью. Когда-то тут шумел лес, о котором заботились калдорай, возведшие аванпост Тен'Ралор, и говорят, что полубог Ло'Гош стоял здесь против Пылающего Легиона в Войне Древних.",
		full = "Пыль здесь не всегда была пылью. Когда-то тут шумел лес, о котором заботились калдорай, возведшие аванпост Тен'Ралор, и говорят, что полубог Ло'Гош стоял здесь против Пылающего Легиона в Войне Древних. Великий Раскол положил всему этому конец, и зелёная долина превратилась в выжженную солнцем равнину, какой она остаётся и сейчас.\n\nПоколениями таурены кочевали по этим равнинам, охотясь на кодо и громоящеров и ища мудрости Матери-Земли, а кентавры неотступно преследовали их ради забавы. Таурены давали отпор, но никогда не из любви к войне: когда приходили люди-кони, они сворачивали шатры и уходили, лишь бы не губить жизни понапрасну. Год мира, год войны — такой была жизнь тауренов, пока не высадились орки Тралла и тролли Черного Копья и не выступили вместе с тауренами Кровавого Копыта против кентавров. После падения Легиона у горы Хиджал Тралл занял восточную часть Степей, прогнал свинобразов из племени Иглогривых, назвал эту землю Дуротаром и воздвиг Оргриммар как её столицу.\n\nЭта земля хранит и более давние горести: говорят, что некий Деторин застал свою возлюбленную Аллурану в объятиях другого, и от его крика из песка поднялся топор Убийца — тот самый клинок, которым он её и убил.",
