	[1414] = {
		name = "Калимдор",
		short = "После того как Раскол сокрушил мир, уцелевшие ночные эльфы намеренно отгородились от остального мира.",
		full = "После того как Раскол сокрушил мир, уцелевшие ночные эльфы намеренно отгородились от остального мира. Среди людей Калимдор сохранился лишь как легенда о земле, что раскололась и ушла под воду, и ни её местоположение, ни очертания не были им известны.\n\nНо она не была утрачена целиком. В последующие годы ночные эльфы навещали кель'дорай, и потому лишь высшие эльфы Кель'Таласа знали, что легенда правдива.\n\nДаже когда пришла Третья война, большинство людей по-прежнему отказывались верить в существование Калимдора, и среди сомневающихся был даже посол Кирин-Тора при дворе короля Теренаса. Лишь немногие вняли предостережению Медива и отплыли на запад — среди них новая Орда Тралла, а следом экспедиция Джайны Праудмур. Нашли они не легенду, а целый континент: льды на севере, пустыни на юге и ночных эльфов, всё ещё хранящих леса между ними.",
