	[1415] = {
		name = "Восточные королевства",
		short = "Восточные королевства не всегда были множеством земель.",
		full = "Восточные королевства не всегда были множеством земель. Когда-то они составляли часть единого континента, пока Великий Раскол не разорвал мир на части и не оставил обломки, которые ныне зовутся Азеротом, Каз Моданом и Лордероном, а Кель'Талас цепляется за север последней из этих расколотых земель, и даже теперь неясно, самостоятельный ли это край или лишь уголок другого.\n\nЧерез эти осколки, словно хребет, проходят через сердце континента горы Каз Модана и Красногорья, а вокруг них живут древние народы: дворфы и гномы в своих глубоких чертогах, люди в своих королевствах, высшие эльфы в своих лесах, а теперь и Отрекшиеся, восставшие там, где некогда жил народ Лордерона. Орки, гоблины, наги и огры тоже нашли дорогу в эти земли, хотя никто из них здесь не родился.\n\nШрамы того первого раскола и поныне определяют суть этих мест. Каждая граница, каждый пролив и каждая полоса затопленной земли между одним королевством и другим помнят, что Восточные королевства когда-то были единым целым — и больше им не являются.",
