	[1418] = {
		name = "Бесплодные земли",
		short = "Бесплодные земли — растрескавшаяся пустыня сухой земли, разбросанных валунов и извилистых каньонов, со всех сторон окружённая горами. Мало кто выживает здесь, кроме койотов, пум и стервятников.",
		full = "Бесплодные земли — растрескавшаяся пустыня сухой земли, разбросанных валунов и извилистых каньонов, со всех сторон окружённая горами. Мало кто выживает здесь, кроме койотов, пум и стервятников.\n\nНа севере лежат руины Ульдамана, творения древних земельников. Когда их раскопали, они дали первые подсказки о высоком происхождении дворфов, и старатели из Стальгорна хлынули сюда в поисках артефактов титанов. Но трогги Каменного Свода, пробудившиеся после тысячелетнего сна, перебили исследователей и теперь с яростным упорством защищают похищенный город. Чуть южнее Ульдамана стоит большая крепость дворфов Черного Железа, которые воюют с ограми из племени Пылевых Выбросов и с драконами, гнездящимися среди отродий черных драконов на востоке.\n\nПозднее здесь был основан Каргат — единственный аванпост Орды в Каз Модане, возведённый, чтобы орки могли следить за своими отступниками-сородичами из клана Черной горы. Сам вождь Тралл послал сюда экспедиционный отряд Каргата, чтобы выследить Ренда Чернорука.",
		source = "https://warcraft.wiki.gg/wiki/Badlands_(Classic)",
