	[1419] = {
		name = "Выжженные земли",
		short = "Выжженные земли носят своё имя по праву. Красная глина под ногами когда-то была бурой землёй, частью тёмного болота под названием Черные топи, пока орочья Орда не распахнула здесь Темный портал и не хлынула в Азерот.",
		full = "Выжженные земли носят своё имя по праву. Красная глина под ногами когда-то была бурой землёй, частью тёмного болота под названием Черные топи, пока орочья Орда не распахнула здесь Темный портал и не хлынула в Азерот. Магия, просочившаяся в тот день, выжгла почву докрасна и умертвила её навсегда. Ныне здесь не растёт ничего, кроме выносливого пустынного кустарника, и не водится ничего, кроме выносливых пустынных тварей: василисков, скорпионов, гиен.\n\nВерховный маг Кадгар и Кирин-Тор возвели Крепость Стражей Пустоты, чтобы следить за руинами врат и не допустить, чтобы сквозь них снова кто-то прошёл. Мир продержался два года, пока Орда Дренора вновь не открыла Портал и не осадила крепость. Когда ритуал Нер'зула начал разрывать Дренор на части, Кадгар и другие маги с помощью Черепа Гул'дана разнесли каменную арку Портала на куски с той стороны, навсегда разорвав мост между мирами.\n\nИ сегодня маги и паладины Крепости Стражей Пустоты несут мрачную стражу у мёртвого Портала — сплочённая, лишённая юмора община, которая никому не доверяет и не прощает ни единой оплошности. Это единственное убежище в краю, где бури с восточного моря стекают по спёкшейся земле, прежде чем успевают принести хоть какую-то пользу.",
		source = "https://warcraft.wiki.gg/wiki/Blasted_Lands_(Classic)",
