	[1420] = {
		name = "Тирисфальские леса",
		short = "Небо над Тирисфальскими лесами уже много лет отливает болезненной зеленью, а деревья цепляются за ту жизнь, что оставила им чума.",
		full = "Небо над Тирисфальскими лесами уже много лет отливает болезненной зеленью, а деревья цепляются за ту жизнь, что оставила им чума. Когда-то здесь при короле Теренасе раскинулись мирные фермы, и поколения тихо жили среди мельниц и тыквенных полей. Всё кончилось, когда Артас Менетил разорил Лордерон и пронёс чуму по деревням, убивая жителей и поднимая их рабами Короля-лича. Братские могилы до сих пор отмечают места, где мёртвых было слишком много, чтобы похоронить их как подобает. Именно у Фермы Балнира, спустя несколько месяцев, Сильвана Ветрокрылая обратила своих банши против Артаса и всадила в рыцаря смерти отравленную стрелу, прежде чем скелеты Кел'Тузада отогнали её.\n\nИз этих руин вышли Отрекшиеся — мёртвые Сильваны, обретшие свободу воли, и они объявили эту землю своей. Их враги так и не ушли отсюда: на севере, в старом Монастыре Алого ордена, засели фанатики Алого ордена, которые жгут и преследуют всех, кто не является человеком.",
		source = "https://warcraft.wiki.gg/wiki/Tirisfal_Glades_(Classic)",
	},
	[1421] = {
		name = "Серебряный бор",
		short = "Серебряный бор, или просто Бор, — огромный древний лес, тянущийся вдоль скалистого западного побережья Лордерона. Местность здесь то почти ровная, то холмистая, и лежит она среди ещё более высоких гор.",
		full = "Серебряный бор, или просто Бор, — огромный древний лес, тянущийся вдоль скалистого западного побережья Лордерона. Местность здесь то почти ровная, то холмистая, и лежит она среди ещё более высоких гор. В лесу царит жуткая тишина, которую лишь изредка нарушает неестественный вой, эхом разносящийся среди деревьев. Замшелые навесы дрожат на холодном ветру, а все деревья больны или умирают. Повсюду разбросаны обветшалые фермы и заброшенные рудники, где теперь обитают самые мрачные обитатели леса.\n\nЭтот лес населён призраками и дик, и узнать его легко по высоким соснам с серебристой корой, возвышающимся над травянистыми пригорками. Когда-то, пока Серебряный бор был пышным и полным жизни, его охранял Альянс. Теперь же он окутан призрачными туманами. Отрекшиеся контролируют северную часть леса и постоянно сражаются с жалкими гноллами-Гнилошкурами. Остатки людского населения удерживают южную часть леса, но они в отчаянии, а их силы растянуты до предела. Даларан часто посылает в Серебряный бор экспедиции, чтобы защищать этих людей и изучать чуму нежити и проклятие воргенов — таинственный недуг, из-за которого его жертвы с восходом луны превращаются в кровожадных воргенов-оборотней.\n\nНа юге лес граничит с Гильнеасом и Предгорьями Хилсбрада, а на севере лежат Тирисфальские леса. Восточной границей Серебряного бора служит озеро Лордамер.\n\nХотя эта территория принадлежит Отрекшимся, их притязания оспаривают волшебники Даларана и приспешники Плети, завладевшие некоторыми разорёнными полями и усадьбами. Гноллы-Гнилошкуры действуют с таинственного Острова Фенриса и яростно нападают на всякого, кто посмеет приблизиться к их делам. На юго-западе лежит Деревня Погребальных Костров, жители которой пали жертвой проклятия верховного мага Аругала и по ночам превращаются в кровожадных воргенов. Сам Аругал обитает неподалёку, в тёмных башнях Крепости Темного Клыка.\n\nВ Серебряном бору часто идут бои: войска Альянса из Южнобережья приходят в эти покинутые леса, чтобы атаковать Гробницу или проникнуть в Крепость Темного Клыка. Это рубеж родины Отрекшихся и самая южная точка, где влияние чумы нежити заметно по растительности.",
		source = "https://warcraft.wiki.gg/wiki/Silverpine_Forest_(Classic)",
	},
	[1422] = {
		name = "Западные Чумные земли",
		short = "Когда-то здесь были прекраснейшие пашни северного Лордерона, лесистые и зелёные; из Андорала они наполняли зернохранилища королевства, а управлялись из чертога в Дольном Очаге.",
		full = "Когда-то здесь были прекраснейшие пашни северного Лордерона, лесистые и зелёные; из Андорала они наполняли зернохранилища королевства, а управлялись из чертога в Дольном Очаге. Это процветание и стало оружием, которым их уничтожили.\n\nПо замыслу Короля-лича Культ Проклятых доставил его чумную энергию на юг в переносных котлах, спрятал их в деревнях, верных культу, а четыре самых больших установил прямо на полях Андорала. Заражено было само зерно, и оно расходилось по всему Лордерону в повозках, которые никто и не думал проверять. Люди, евшие собственный хлеб, заболевали, умирали и восставали вновь рабами Короля-лича. Леса так и не оправились. Сосны стоят серые, с побуревшей хвоей, под пеленой болезненного тумана, а их стволы вздулись от опухолевых наростов.\n\nТот порядок, что здесь ещё остался, был восстановлен после падения королевства, когда Алый орден захватил Крепость Марденхольд в Дольном Очаге и оттуда начал наступление на нежить, державшую остальную часть этой земли. Посреди всего этого лишь одно место хранит покой: Гробница Утера, освящённая в память Утера Светоносного, — земля, которой скверна так и не коснулась.",
		source = "https://warcraft.wiki.gg/wiki/Western_Plaguelands_(Classic)",
	},
	[1423] = {
		name = "Восточные Чумные земли",
		short = "Когда-то здесь были пашни, и деревни Восточных лесов были разбросаны вокруг Стратхольма, второго города Лордерона. Ничего из этого не осталось.",
		full = "Когда-то здесь были пашни, и деревни Восточных лесов были разбросаны вокруг Стратхольма, второго города Лордерона. Ничего из этого не осталось. Почва теперь бурая и больная, деревья раздулись, превратившись в грибы, а воздух полон оранжевого тумана.\n\nИменно в Стратхольм пришёл принц Артас в поисках источника чумы, уже поразившей горожан. Лорд Утер, глава ордена Серебряной Длани, отказался позволить ему истребить жителей города. Артас лишил его командования, тут же распустил орден Серебряной Длани и сам предал жителей Стратхольма мечу, лишь бы они не восстали воинами Плети. На этом он не остановился: он преследовал повелителя ужаса Мал'Ганиса до самого севера, вернулся рыцарем смерти и убил собственного отца, положив конец королевству Лордерон.\n\nАлександрос Могрейн собрал из остатков Серебряной Длани Орден, чтобы отвоевать руины, и захватил Длань Тира и половину Стратхольма, но после его смерти орден раскололся на Серебряный Рассвет и Алый орден, который по сей день удерживает эти поля, бесконечно воюя с Плетью и не принимая никого другого.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Plaguelands_(Classic)",
	},
	[1424] = {
		name = "Предгорья Хилсбрада",
		short = "Земля Хилсбрада плодородна, а холмы зелены, и путники говорят, что именно так выглядел весь Лордерон до прихода чумы.",
		full = "Земля Хилсбрада плодородна, а холмы зелены, и путники говорят, что именно так выглядел весь Лордерон до прихода чумы. В этом столько же жестокости, сколько и утешения: земля помнит то, что было утрачено повсюду, а люди, которые её удерживают, ведут ту же войну, что погубила всё остальное.\n\nВ начале Второй войны орочьи налётчики обрушились на её прибрежные городки, а сам Оргрим Молот Рока двинулся на Крепость Дарнхольд, чтобы освободить Зул'джина из темницы. Спустя десятилетия этими холмами прошёл уже Тралл: он собрал рассеянные орочьи кланы, а затем ночью пробрался в Южнобережье, чтобы угнать его корабли и переправить новую Орду через море в Калимдор.\n\nТо, что начали орки, продолжили Отрекшиеся. Они сделали Мельницу Таррен своим самым южным владением и превратили её в плацдарм против людей Южнобережья и Хилсбрадских полей, стойко державшихся за Альянс.\n\nТеперь среди пашен разбросаны сосновые рощи, а дороги по-прежнему пересекают пастбища, ведя к мрачным поселениям Отрекшихся на севере, будто сама земля всё ещё ждёт, какая из сторон её удержит.",
		source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Foothills_(Classic)",
	},
	[1425] = {
		name = "Внутренние земли",
		short = "После Войны Трех Кланов дворфы Громового Молота покинули свои туннели в Грим Батоле, ушли на север и построили жилища под открытым небом, на Заоблачном Пике.",
		full = "После Войны Трех Кланов дворфы Громового Молота покинули свои туннели в Грим Батоле, ушли на север и построили жилища под открытым небом, на Заоблачном Пике. От камня и горна они обратились к небу и крыльям и так тесно связали себя с дикими грифонами этого края, что в честь этих уз воздвигли в своём городе огромного каменного грифона. Лесные тролли, издавна владевшие этой землёй, остатки некогда великой империи Амани, считали дворфов захватчиками земли предков и нападали на гнездовья при каждом удобном случае.\n\nКогда во время Второй войны сюда хлынула Орда, тан Курдран Громовой Молот и его всадники, до той поры и не подозревавшие о существовании таких захватчиков, обрушились на колонны орков с неба с молотами, напитанными силой бури, и преследовали их без передышки. Оргрим Молот Рока надеялся втянуть силы Альянса во Внутренние земли, чтобы беспрепятственно ударить по Кель'Таласу, но Андуин Лотар разгадал этот замысел и сам пришёл на помощь Курдрану, и вместе они разбили захватчиков и отбросили их к Альтеракским горам. За это Курдран поклялся, что его народ будет помогать Альянсу.",
		source = "https://warcraft.wiki.gg/wiki/Hinterlands_(Classic)",
	},
	[1426] = {
		name = "Дун Морог",
		short = "Дун Морог покрыт глубокими снегами и со всех сторон окружён горами Каз Модана, а его перевалы неусыпно охраняют дворфские войска.",
		full = "Дун Морог покрыт глубокими снегами и со всех сторон окружён горами Каз Модана, а его перевалы неусыпно охраняют дворфские войска. Прежде чем эти горы стали чьими-то ещё, они принадлежали снежным троллям из племени Мерзлогривов, которые поселились здесь в давние времена, отколовшись от империи Драккари.\n\nВсё изменилось, когда из Ульдамана выбрались первые гномы и направили свою смекалку на то, чтобы выжить и в холоде, и среди троллей, вырыв в глубине гор укреплённые жилища. Пятьсот лет спустя вслед за ними из Ульдамана вышли дворфы, привлечённые теми же горами, что виднелись им на горизонте, и под самой высокой из них воздвигли Стальгорн. Обнаружив, что гномы уже живут по соседству, два народа заключили дружбу, которая никогда не прерывалась: дворфы помогли своей силой построить Гномреган, а гномы поделились секретами своих механизмов. Вместе их армии разбили троллей Мерзлогривов и загнали уцелевших обратно в холмы, навсегда положив конец их власти над этой землёй.\n\nГномрегана больше нет — он лежит в руинах, а его жители ютятся в Стальгорне.",
		source = "https://warcraft.wiki.gg/wiki/Dun_Morogh_(Classic)",
	},
	[1427] = {
		name = "Тлеющее ущелье",
		short = "Когда-то это была зелёная земля, часть Красногорья, пока более двухсот тридцати лет назад не разверзлась сама земля.",
		full = "Когда-то это была зелёная земля, часть Красногорья, пока более двухсот тридцати лет назад не разверзлась сама земля.\n\nВо время Войны Трех Кланов тан-чародей дворфов Черного Железа Тауриссан искал оружие, способное сокрушить его врагов. Он и семеро самых верных его дворфов проникли в недра мира и воззвали к силам, которым следовало бы спать и дальше. Откликнулся же не слуга, а повелитель — древний Повелитель Огня Рагнарос. Его пробуждение вырвало из земли Черную гору, опалило землю на многие мили вокруг и обратило в щебень столицу Черного Железа, город Тауриссан, похоронив его под горой. Опалённые степи к югу стали называться Пылающими степями, а эта разорённая долина на севере — Тлеющим ущельем.\n\nПосле этой катастрофы не все дворфы Черного Железа сохранили верность своему клану. Часть из них откололась, назвав себя Братством Тория, и построила Лагерь Братства Тория над огромным карьером, который их бывшие сородичи прорыли в дне долины, и теперь они наблюдают за трудами Черного Железа сверху.",
		source = "https://warcraft.wiki.gg/wiki/Searing_Gorge_(Classic)",
	},
	[1428] = {
		name = "Пылающие степи",
		short = "Небо над Пылающими степями никогда не теряет багрового оттенка, озаряемое внезапными извержениями Черной горы, и земля здесь никогда не остывает.",
		full = "Небо над Пылающими степями никогда не теряет багрового оттенка, озаряемое внезапными извержениями Черной горы, и земля здесь никогда не остывает. За двести лет до открытия Темного портала сюда пришли изгнанные из Стальгорна дворфы Черного Железа. Их тан-чародей Тауриссан пытался призвать прислужников-элементалей, чтобы выиграть Войну Трех Кланов против кланов Бронзобородов и Громового Молота. Откликнулся же не прислужник, а Повелитель Огня Рагнарос, некогда изгнанный титанами. Его появление расплавило окрестные горы, воздвигло вулкан в самом сердце взрыва и уничтожило дворфов, что его призвали. То, что лежало к северу от новой вершины, стало Тлеющим ущельем, а то, что к югу, — Пылающими степями, изуродованными с тех пор навсегда.\n\nВо время Первой войны орки поселились на склонах вулкана и удерживали Вершину Черной горы как свою твердыню на протяжении Второй. Позднее орки клана Черной горы вернулись и остаются там до сих пор, следуя старым жестоким обычаям, что царили до перемирия Тралла. Верхние уровни вершины занимают черные драконы под началом Нефариана, и говорят, что где-то глубоко под всем этим по-прежнему таится Рагнарос.",
		source = "https://warcraft.wiki.gg/wiki/Burning_Steppes_(Classic)",
	},
	[1429] = {
		name = "Элвиннский лес",
		short = "Когда в Первую войну пришли орки, тысячи их прошли через Элвиннский лес и окружили Штормград, отрезав его от всего, кроме моря.",
		full = "Когда в Первую войну пришли орки, тысячи их прошли через Элвиннский лес и окружили Штормград, отрезав его от всего, кроме моря. Рыцарь-защитник Андуин Лотар повёл рыцарей Штормграда в атаку прямо через лес, внезапно ударив по орочьему арьергарду и рассеяв его. Это дало городу время, но недостаточно. Вскоре вождь Чернорук захватил Златоземье и Луноречье, последние городки между Ордой и королём, и крепость Штормграда была разграблена. Лотар увёл уцелевших к морю и дальше, в Лордерон, а руины города на время достались клану Бушующего Шторма. Разбросанные по округе разбитые орочьи катапульты до сих пор гниют здесь — единственное напоминание о той оккупации.\n\nВиноградники Североземья к востоку от города когда-то были гордостью земледельцев Штормграда. Когда Гильдии каменщиков так и не заплатили за годы, потраченные на восстановление разрушенной столицы, а знать предпочла распустить гильдию, чем расплатиться с долгом, ярость главы гильдии Эдвина ван Клифа выплеснулась в бунты, в которых погибла королева Тиффин Эллериан Ринн и родилось Братство Справедливости. Братство прогнало земледельцев из Североземья и захватило его поля.",
		source = "https://warcraft.wiki.gg/wiki/Elwynn_Forest_(Classic)",
	},
	[1430] = {
		name = "Перевал Мертвого Ветра",
		short = "Перевал Мертвого Ветра прорезает горы центрального Азерота, соединяя Сумеречный лес с Болотом Печали. Два десятка лет назад его считали частью Красногорья.",
		full = "Перевал Мертвого Ветра прорезает горы центрального Азерота, соединяя Сумеречный лес с Болотом Печали. Два десятка лет назад его считали частью Красногорья.\n\nВ самом центре этого зазубренного края стоит Башня из слоновой кости, Каражан, некогда средоточие власти тёмного волшебника Медива, и из неё в землю сочится злая магия. Деревья здесь окаменели и лишены листвы, а по каньону с воем проносится страшный ветер. В глубине перевала бродят огры, демоны, нежить и немногочисленные люди-цыгане, и шёпотом говорят, что Башней из слоновой кости завладела новая сила и что огры и демоны покорны ей.",
		source = "https://warcraft.wiki.gg/wiki/Deadwind_Pass_(Classic)",
	},
	[1431] = {
		name = "Сумеречный лес",
		short = "Над Сумеречным лесом лежит покров неестественной ночи, и он так и не рассеялся.",
		full = "Над Сумеречным лесом лежит покров неестественной ночи, и он так и не рассеялся. То, что когда-то было прекрасной частью Элвиннского леса, стало проклятой, умирающей землёй: деревья искривились под чёрным туманом, мёртвые восстали из могил, а вместе с самой тьмой сюда прокрались воргены, привлечённые действием Косы Элуны. Огры, наседающие со стороны Перевала Мертвого Ветра, лишь усугубили беды.\n\nЗащита Штормграда давно перестала здесь что-либо значить, и оставшиеся жители научились стоять на своём без неё. Их ополчение, Ночной Дозор, патрулирует дороги и охраняет Темнолесье от всего, что движется в тенях: от воинов-скелетов и вурдалаков, свирепых воргенов, а вдобавок и от людей из Братства Справедливости.\n\nВ сердце леса лежит кратер давно потухшего вулкана, окутанный сумерками, более мягкими, чем окружающая тьма. В нём стоит одно из Великих Древ, чьи корни тянутся к Изумрудному Сну, и влияние спящих друидов накладывает отпечаток на всё, что растёт поблизости. За ним простираются заброшенные фермы и широко раскинувшиеся могилы Кладбища Вороньего Холма, которое год за годом наполняется с тех пор, как пала тьма.",
		source = "https://warcraft.wiki.gg/wiki/Duskwood_(Classic)",
	},
	[1432] = {
		name = "Лок Модан",
		short = "Воды Лок Модана покоятся в колыбели серого камня, удерживаемые Каменной Плотиной — творением дворфских инженеров, которому не найти равных во всём Азероте.",
		full = "Воды Лок Модана покоятся в колыбели серого камня, удерживаемые Каменной Плотиной — творением дворфских инженеров, которому не найти равных во всём Азероте. Со всех сторон отвесно поднимаются горы, поросшие редкими соснами и берёзами, а само озеро лежит тихо и спокойно, словно его ничто никогда не тревожило.\n\nКогда-то озеро было полем битвы. Во Вторую войну орки Орды хлынули в этот край и дали здесь бой Альянсу. Стальгорн выстоял. Его дворфы отбросили орков и отвоевали Лок Модан, но обломки той войны так и не убрали до конца: разбитые катапульты и сокрушённые баллисты до сих пор лежат, наполовину затонув, по всему дну озера и на его островах — единственное свидетельство того, что эти спокойные воды когда-то были местом бойни.",
		source = "https://warcraft.wiki.gg/wiki/Loch_Modan_(Classic)",
	},
	[1433] = {
		name = "Красногорье",
		short = "Красногорье лежит к востоку от Элвиннского леса, к северо-востоку от Сумеречного леса и к югу от Пылающих степей.",
		full = "Красногорье лежит к востоку от Элвиннского леса, к северо-востоку от Сумеречного леса и к югу от Пылающих степей.\n\nЭтот идиллический край бурных рек, высоких вязов и крутых подъёмов находится под защитой Штормграда, хотя со времён Второй войны формально независим. Он остаётся одним из последних мирных уголков Азерота: его жители спокойны и довольны жизнью и снабжают Штормград лесом, рыбой и урожаем. И всё же мир здесь несовершенен: отряд орков клана Черной горы из Пылающих степей удерживает Крепость Каменной Стражи, хотя пока они держатся особняком. В сравнении с разорённым Западным Краем Красногорье всё ещё держится.\n\nНа северном берегу Озера Безмолвия стоит городок Приозерье, осаждённый гноллами и орками клана Черной горы, что спускаются с окрестных холмов. К югу от него перекрёсток, известный как Три Угла, связывает Приозерье с Элвиннским и Сумеречным лесами, а по Озерному тракту — с Крепостью Каменной Стражи, и на этой дороге хозяйничают дракончики, гноллы, мурлоки и дикие звери.\n\nГладь озера кажется достаточно спокойной, но под ней таятся мурлоки, и не утихают слухи о морском чудовище в его глубинах.",
		source = "https://warcraft.wiki.gg/wiki/Redridge_Mountains_(Classic)",
	},
	[1434] = {
		name = "Тернистая долина",
		short = "Тернистая долина — огромные джунгли к югу от Сумеречного леса. Этот влажный тропический лес патрулируют тролли джунглей, вдоль побережья охотятся наги, а колючие лианы и звери делают путешествие опасным.",
		full = "Тернистая долина — огромные джунгли к югу от Сумеречного леса. Этот влажный тропический лес патрулируют тролли джунглей, вдоль побережья охотятся наги, а колючие лианы и звери делают путешествие опасным.\n\nКогда-то долина была сердцем империи Гурубаши, чьи великие города стояли по всему краю. После падения империи эти города обратились в руины, хотя тролли по-прежнему живут среди них. Зул'Гуруб на северо-востоке некогда был столицей Гурубаши.\n\nПиратская бухта изначально была маленьким портовым городком, основанным людьми, пока его не захватили тролли. Позднее гоблины картеля Хитрой Шестеренки изгнали троллей из бухты и забрали её себе, превратив в центр своих операций в Восточных королевствах.\n\nНа севере стоит лагерь, возведённый экспедицией полковника Курцена. Там разумом полковника завладел огр-маг Май'Зот, который с помощью артефакта под названием Око разума подчинил себе волю Курцена и стал командовать его людьми. Часть солдат Курцена восстала против своего одержимого командира и бежала на запад, основав лагерь повстанцев ему наперекор.",
		source = "https://warcraft.wiki.gg/wiki/Stranglethorn_Vale_(Classic)",
	},
	[1435] = {
		name = "Болото Печали",
		short = "Под чёрной водой болота лежит храм, более древний, чем печаль, что дала имя этому месту.",
		full = "Под чёрной водой болота лежит храм, более древний, чем печаль, что дала имя этому месту. Когда пала империя Гурубаши, отступническое племя троллей Атал'ай бежало в топи и воздвигло Храм Атал'Хаккара, где проводило жуткие обряды, чтобы призвать обратно в мир своего тёмного лоа, Хаккара Свежевателя Душ. Их магия исказила растения и зверей вокруг храма так, что скверну уже невозможно было не заметить. Изера, хозяйка снов, узнала о замыслах культа и обратила против него свою силу, затопив храм под самой большой трясиной, прежде чем Хаккар смог вернуться. Но она не верила, что тролли навсегда отрекутся от своего бога. Она поручила своему супругу Эраникусу и сонму зелёных драконов вечно стеречь руины, чтобы их больше никогда не использовали для того, чтобы выпустить в мир подобное зло. Зелёные драконы по-прежнему по её повелению патрулируют эти болота, а затонувший храм остаётся запечатанным под водой — его стерегут, а не уничтожают.",
		source = "https://warcraft.wiki.gg/wiki/Swamp_of_Sorrows_(Classic)",
	},
	[1436] = {
		name = "Западный Край",
		short = "Ветер теперь беспрепятственно гуляет по полям Западного Края, ведь не осталось ничего высокого, что могло бы его остановить. Когда-то это была житница Штормграда, поколениями кормившая молодое королевство.",
		full = "Ветер теперь беспрепятственно гуляет по полям Западного Края, ведь не осталось ничего высокого, что могло бы его остановить. Когда-то это была житница Штормграда, поколениями кормившая молодое королевство.\n\nКогда Гильдии каменщиков так и не заплатили за восстановление Штормграда после Второй войны, а стража обратилась против их протестов, глава гильдии Эдвин ван Клиф увёл своих людей скрываться в сельской глуши, лишь бы не предстать перед судом короля Вариана. Там они стали Братством Справедливости, и под амбаром в Луноречье ван Клиф нашёл старую сеть шахт, достаточно глубокую, чтобы тайно строить в ней оружие, которым он собирался сжечь Штормград с моря. Он прогнал земледельцев, нанял гноллов из стаи Речной Лапы охранять землю и приказал своим людям сжечь поля и засолить почву, чтобы на ней больше ничего не росло.\n\nШтормград, опустошивший свою казну, оставил Западный Край выживать самостоятельно. Откликнулся лишь Гриан Камнегрив, собравший Народное ополчение на Сторожевом холме, когда никакая армия так и не пришла.\n\nЗасоленные им поля так и не простили этого Западному Краю. Там, где когда-то пшеница стояла в человеческий рост, трава до сих пор растёт жёлтой и редкой.",
		source = "https://warcraft.wiki.gg/wiki/Westfall_(Classic)",
	},
	[1437] = {
		name = "Болотина",
		short = "Ниже плотины лежит холодное серое болото: над его реками и прудами стелется туман, с трёх сторон его обступают горы, а на западе открывается море.",
		full = "Ниже плотины лежит холодное серое болото: над его реками и прудами стелется туман, с трёх сторон его обступают горы, а на западе открывается море. Повсюду разбросаны обломки — остатки дворфских крепостей, что некогда удерживали эту землю. Теперь ею вместо них владеют мурлоки, дикие звери и орки-отступники, а Гавань Менетилов — единственная настоящая опора Альянса в этих краях.\n\nЭта гавань не всегда принадлежала Альянсу. Когда началась Вторая война, Оргрим Молот Рока построил свой флот вторжения на маленьком острове в Бухте Барадин, чтобы его корабли могли атаковать берега Лордерона, не сталкиваясь с его сухопутной обороной. Болотина заплатила за это: орки и драконы нещадно кормились этой землёй, и дичь стала редкостью. После войны порт отстроили заново и переименовали в Гавань Менетилов в честь Теренаса Менетила II.\n\nЗатем пал Грим Батол. Красные драконы, порабощённые кланом Драконьей Пасти и вынужденные служить ему там, обрушились на своих поработителей, едва обретя свободу, и клан был разбит, а его уцелевшие разбежались по диким землям. Алекстраза сочла долгом своей стаи держать гору запечатанной, и с тех пор красные драконы несут над ней стражу.",
		source = "https://warcraft.wiki.gg/wiki/Wetlands_(Classic)",
	},
	[1438] = {
		name = "Тельдрассил",
		short = "Когда Малфурион Ярость Бури исчез в Изумрудном Сне, его место во главе Круга Кенария занял верховный друид Фэндрал Олений Шлем, который убедил Круг Древних, что пришло время вырастить новое Древо Жизни и вернуть бессмертие, утраченное ночными эльфами.",
		full = "Когда Малфурион Ярость Бури исчез в Изумрудном Сне, его место во главе Круга Кенария занял верховный друид Фэндрал Олений Шлем, который убедил Круг Древних, что пришло время вырастить новое Древо Жизни и вернуть бессмертие, утраченное ночными эльфами. В Сокрытом Море они вырастили Тельдрассил, венец земли, и построили в его ветвях Дарнасс. Но Ноздорму, благословивший первое Древо Жизни, отказал в благословении этому, назвав такое желание высокомерным, и бессмертие, которого жаждали ночные эльфы, так и не пришло.\n\nСо временем земли на вершине Тельдрассила оказались во власти зловещей силы. Фурболги и гриллы в его лесах обезумели, среди деревьев появились сатиры, а огромные черепахи и крепкозубы, что некогда плавали в водах вокруг древа, бежали прочь и выбрасывались на берега Темных берегов, чтобы там умереть. Источник этой скверны по-прежнему остаётся загадкой, а Малфурион так и не вернулся из Сна, чтобы его отыскать.",
		source = "https://warcraft.wiki.gg/wiki/Teldrassil_(Classic)",
	},
	[1439] = {
		name = "Темные берега",
		short = "Серый туман чаще всего стелется вдоль этого побережья, и ночные эльфы издавна считают его предостережением.",
		full = "Серый туман чаще всего стелется вдоль этого побережья, и ночные эльфы издавна считают его предостережением. Дожди и скалы делают эту землю неприветливой, и все попытки заселить её дальше торгового поселения Аубердин ни к чему не привели.\n\nДесять тысяч лет назад здесь стояли города-близнецы Амет'Аран и Башал'Аран, которыми правил Атрикус Нарассин. Когда Война Древних сокрушила мир и надвинулся Великий Раскол, Атрикус поклялся своему народу, что спасёт его. Он сдержал букву своего обещания, но предал его дух: он заключил души своих подданных в камни душ, уверяя, что это вечная жизнь, а на деле высасывал их, чтобы питать собственную силу. Города обратились в руины, и то, что ныне бродит среди их камней, не обрело полного покоя.\n\nПосле Третьей войны Фэндрал Олений Шлем привёл на Темные берега друидов Круга Кенария и посадил на этом берегу новое Древо Жизни — Тельдрассил.",
		source = "https://warcraft.wiki.gg/wiki/Darkshore_(Classic)",
	},
	[1440] = {
		name = "Ясеневый лес",
		short = "Ясеневый лес — древняя чаща, полная старых деревьев и старой магии, и за неё никогда не переставали сражаться.",
		full = "Ясеневый лес — древняя чаща, полная старых деревьев и старой магии, и за неё никогда не переставали сражаться.\n\nОрки клана Песни Войны впервые пришли сюда лесорубами. Гоблины под началом Нилока Гридфингерса вырубали деревья, пока местные фурболги не отбросили их, и тогда Громмаш Адский Крик разгромил фурболгов, а затем и Часовых, чтобы сохранить помощь гоблинов. Сам Кенарий явился, чтобы возродить срубленное, и это стоило ему жизни: повелители Пылающего Легиона обратили его доверие в ловушку, и Громмаш сразил его.\n\nХудшее ждало впереди, когда Легион всей мощью двинулся на Ясеневый лес. Инферналы Архимонда пылающими глыбами падали с неба, а с востока хлынули нежить и демоны, сметая разрозненные армии ночных эльфов, орков и людей, прежде чем устремиться дальше, к горе Хиджал. Тиранда Шелест Ветра пробудила Малфуриона от Изумрудного Сна, и он увидел, что лес, который он помнил, пожирает пламя Скверны и душит порча.\n\nТот давний спор так и не закончился. Ночные эльфы по-прежнему удерживают Астранаар и свои разрозненные убежища; Орда же продвинула лагеря Песни Войны далеко на юг и восток, валя лес и оттесняя Часовых. Ни одна из сторон так и не довела битву за эти леса до конца.",
		source = "https://warcraft.wiki.gg/wiki/Ashenvale_(Classic)",
	},
	[1441] = {
		name = "Тысяча Игл",
		short = "Каньон тянется глубокий и сухой, его дно теряется среди высоченных плато, пока на востоке он не выходит к Мерцающей равнине — огромному солончаку под широким небом.",
		full = "Каньон тянется глубокий и сухой, его дно теряется среди высоченных плато, пока на востоке он не выходит к Мерцающей равнине — огромному солончаку под широким небом. Восход солнца, если смотреть с Заставы Вольного Ветра или с высот вокруг Пика Темного Облака, — поистине величественное зрелище над столь бесплодным краем. Друид Квентин задавался вопросом, не является ли здешняя суровая сушь, соседствующая с пышными джунглями Фераласа, вовсе не естественной, а следом какой-то странной магии, наложенной на эту землю.\n\nВысокие плато принадлежат тауренам, и Застава Вольного Ветра служит им твердыней среди них. Эту землю им не удалось удержать без борьбы. Их теснили местные кентавры, а хуже того — против них обратились их собственные сородичи из племени Зловещего Тотема, так что тауренам Заставы Вольного Ветра пришлось сражаться племя против племени за эти высокогорья. Лишь с помощью Орды им удалось отбросить кентавров и Зловещий Тотем.",
		source = "https://warcraft.wiki.gg/wiki/Thousand_Needles_(Classic)",
	},
	[1442] = {
		name = "Когтистые горы",
		short = "Пик Каменного Когтя всегда принадлежал духам прежде, чем какому-либо народу.",
		full = "Пик Каменного Когтя всегда принадлежал духам прежде, чем какому-либо народу. На его вершине ночные эльфы хранят курган и поляну, где общаются с природой, а таурены тоже почитают его священным, ведь именно здесь бессмертный Оракул некогда следил за нитями судьбы, что сплетала Мать-Земля. Легенда гласит, что первые таурены, поселившиеся в этих горах, подняли пылающие тотемы на самые высокие утёсы и разожгли костры в честь Ан'ше, чтобы выжечь тьму, цеплявшуюся за камень.\n\nНиже по склону Элуна давным-давно благословила источник даром исцеления. Позднее ближайшие вершины заняли гарпии: они пленили гнездившихся там виверн и осквернили воды источника. Против них выступил Тралл, а рядом с ним — Кэрн Кровавое Копыто и его таурены; они разбили отряд кентавров, добыли Руну Очищения и очистили то, что осквернили гарпии. Освобождённые виверны подняли их на самый Пик.\n\nНа юге того древнего мира с землёй больше нет. Торговая компания обчистила Утес Ветрорезов догола: вырубила деревья, задушила воздух копотью и отравила воду маслом и отходами, пока горные духи не взвыли так громко, что их услышали шаманы даже в Оргриммаре.",
		source = "https://warcraft.wiki.gg/wiki/Stonetalon_Mountains_(Classic)",
	},
	[1443] = {
		name = "Пустоши",
		short = "Терадрас, дочь Теразан Каменной Матери, некогда дремала под плодородной степью.",
		full = "Терадрас, дочь Теразан Каменной Матери, некогда дремала под плодородной степью. Шаманы-таурены, веря, что внизу обитает сама Мать-Земля, десятилетиями взывали к ней, пока наконец им не ответили — но не Мать-Земля, а Терадрас, в ярости пробуждённая ото сна. Чтобы восстановить своё ослабевшее тело, она стала питаться землёй, и луга погибли в одно мгновение. То, что осталось, таурены назвали Пустошами.\n\nЗейтар, сын повелителя лесов Кенария, пришёл, чтобы сковать её, но вместо этого полюбил её, и она ответила ему взаимностью. От их союза родились кентавры, и первым же их деянием стало убийство собственного отца. Они быстро расплодились и изгнали тауренов с этой земли, положив начало векам войны между двумя народами.\n\nТерадрас и поныне обитает в Мародоне, под западными каньонами, и именно там, по преданию кентавров, зародился их народ.",
		source = "https://warcraft.wiki.gg/wiki/Desolace_(Classic)",
	},
	[1444] = {
		name = "Фералас",
		short = "Фералас странно выделяется среди соседей: это тропический лес из древних деревьев там, где окрестные пустоши сулят лишь пыль.",
		full = "Фералас странно выделяется среди соседей: это тропический лес из древних деревьев там, где окрестные пустоши сулят лишь пыль. Среди его зелени разбросаны эльфийские руины, наполовину поглощённые корнями и лианами, и величайшая из них — погребённый город, Забытый Город.\n\nТеперь Фераласом владеют огры Гордунни, и сделали они его своим, разрушая. Они вырубили целые участки леса, а их скверна легла на землю, словно болезнь. За стенами Забытого Города их отряды жгут деревни и убивают путников в южных лесах — это порча, расползающаяся по диким землям, и корни её уходят в руины внизу.\n\nТаурены из племени Зловещего Тотема до сих пор разрозненно живут в этом краю, преследуемые теми, кто помнит, что сотворило их племя.",
		source = "https://warcraft.wiki.gg/wiki/Feralas_(Classic)",
	},
	[1445] = {
		name = "Пылевые топи",
		short = "Комары здесь не унимаются никогда, как и грязь.",
		full = "Комары здесь не унимаются никогда, как и грязь. Деревья так густо сплетают над водой свои листья, что солнечный свет пробивается лишь клочьями, а на солоноватых отмелях, где море встречается с болотом, поджидают кроколиски и мурлоки. На юге черные драконы собираются в таком количестве, что местные попросту зовут это место Драконьими топями.\n\nПервый настоящий дом в этой глуши основала Джайна Праудмур: после битвы у горы Хиджал она привела сюда свой народ и основала Терамор на скалистом острове. Стены её города сверкают, но они же и ограничивают её: за разбросанными заставами на дороге к Степям болото остаётся таким же диким, как и прежде, а её гарнизон редеет из-за тихого дезертирства, которое никто не может объяснить.\n\nИменно здесь мир между Ордой и Альянсом рухнул окончательно. Адмирал Даэлин Праудмур привёл флот Кул Тираса против Орды в эти болота, и последовавшая стычка закончилась его гибелью, обратив перемирие в открытую вражду.\n\nДеревня Гиблотопь стоит там, где огры Каменного Молота открыли свои ворота Орде. За ней дорога к Степям лежит пустая и приходит в упадок, и стерегут её лишь ящеры и пауки, которые всегда были хозяевами этой земли.",
		source = "https://warcraft.wiki.gg/wiki/Dustwallow_Marsh_(Classic)",
	},
	[1446] = {
		name = "Танарис",
		short = "Песок заполнил место, где когда-то стояли джунгли. До того как мир раскололся, Танарис был зелёным и считался владением империи Гурубаши.",
		full = "Песок заполнил место, где когда-то стояли джунгли. До того как мир раскололся, Танарис был зелёным и считался владением империи Гурубаши. Когда Великий Раскол разорвал землю, джунгли погибли, а то, что осталось, спеклось в дюны и камень. Одно из племён троллей оказалось отрезанным здесь, когда отступила вода, и за долгие последующие годы их тела и обычаи покорились пустыне, пока они не перестали быть прежними троллями и не стали песчаными троллями, племенем Песчаной Бури, народом, созданным землёй, что заточила его.\n\nГоблины картеля Хитрой Шестеренки избрали эту пустошь для своей торговли и основали Прибамбасск и Порт Картеля, потому что пустыня — самое близкое подобие их затонувшей родины, где Калимдор позволяет им поселиться. Причалы Порта Картеля тянутся к лежащим вдали островам, но гоблины держат свои корабли при себе и не желают перевозить через море никакой другой народ.\n\nПод дюнами и южными горами на многие мили тянутся туннели, по большей части не нанесённые на карту, и те, кто спускается туда, не всегда возвращаются, чтобы рассказать, что они нашли.",
		source = "https://warcraft.wiki.gg/wiki/Tanaris_(Classic)",
	},
	[1447] = {
		name = "Азшара",
		short = "Уже десять тысяч лет в Азшаре царит осень: деревья пылают оранжевым и алым над утёсами, что обрываются к кораллам, среди которых до сих пор лежит город.",
		full = "Уже десять тысяч лет в Азшаре царит осень: деревья пылают оранжевым и алым над утёсами, что обрываются к кораллам, среди которых до сих пор лежит город. Азшара была когда-то величайшим городом из всех, что воздвигли ночные эльфы, и когда пришла Война Древних, большая его часть ушла в море. Несколько разрушенных зданий всё ещё цепляются за склон утёса, глядя вниз на собственные руины под водой.\n\nМного позже, когда Иллидан Ярость Бури бежал на север от горы Хиджал вместе со своими нагами, мур'гулами и сатирами, он пронёсся по побережью Азшары, разоряя гавани ночных эльфов, чтобы никто не смог последовать за ним к Гробнице Саргераса. За ним по пятам шли Майев Песнь Теней и её Стражи, усмиряя обезумевших тварей, которых он оставлял на своём пути.",
		source = "https://warcraft.wiki.gg/wiki/Azshara_(Classic)",
	},
	[1448] = {
		name = "Оскверненный лес",
		short = "Деревья Оскверненного леса не столько растут, сколько гниют. Их кора сочится болезненной сукровицей, их листья свисают чёрными и скрученными, а звери под ними рождаются искажёнными и голодными от скверны, пропитавшей почву.",
		full = "Деревья Оскверненного леса не столько растут, сколько гниют. Их кора сочится болезненной сукровицей, их листья свисают чёрными и скрученными, а звери под ними рождаются искажёнными и голодными от скверны, пропитавшей почву.\n\nЭта гниль не была случайностью природы. Когда Пылающий Легион рвался к горе Хиджал, Архимонд приказал сломить лес, чтобы ослабить ночных эльфов, охранявших гору, и повелитель ужаса Тихондриус исполнил этот приказ с помощью чернокнижной реликвии чудовищной силы — Черепа Гул'дана. Земля ответила тем, что стала умирать изнутри: древни прогнили и озлобились, звери мутировали, а сама земля оказалась отравлена.\n\nИменно здесь Иллидан Ярость Бури сделал выбор, определивший всю его дальнейшую жизнь. Узнав, что череп можно обратить против той самой скверны, которую он породил, Иллидан в одиночку отправился в Оскверненный лес, сразил Тихондриуса и забрал реликвию себе. После этого он не отдал её. Жажда магии оказалась в нём сильнее осторожности, и за то, что он воспользовался силой самого Легиона, его изгнал собственный брат Малфурион.",
		source = "https://warcraft.wiki.gg/wiki/Felwood_(Classic)",
	},
	[1449] = {
		name = "Кратер Ун'Горо",
		short = "Кратер Ун'Горо, огороженный стенами, лежит между тремя пустынями — зелёная рана, врезавшаяся в юг Калимдора, где мир словно забывает быть бесплодным.",
		full = "Кратер Ун'Горо, огороженный стенами, лежит между тремя пустынями — зелёная рана, врезавшаяся в юг Калимдора, где мир словно забывает быть бесплодным. По его джунглям бродят динозавры древнее самой памяти, некоторые вырастают до размеров, каких не должно достигать ни одно живое существо, и среди них спокойно расхаживают элементали земли и огня. На гребнях наверху стоят пилоны, назначение которых никто так и не смог объяснить.\n\nВо время Войны Зыбучих песков ночных эльфов оттеснили через этот кратер к самому краю пустыни Танарис, и там натиск киражей захлебнулся. Что-то в самом Ун'Горо не позволило захватчикам завладеть этой землёй, хотя никто так и не сказал, что именно.\n\nЭкспедиция под началом Виллидена и Холании Маршал однажды попыталась закрепиться здесь, но свирепость кратера оказалась им не по силам. Их лагеря были разорены, а уцелевшие бежали на возвышенность и заняли оборону там, где ныне находится Укрытие Маршалла.",
		source = "https://warcraft.wiki.gg/wiki/Un'Goro_Crater_(Classic)",
	},
	[1450] = {
		name = "Лунная поляна",
		short = "Лунная поляна покоится в кольце гор — укрытая долина, где лес никогда не знал скверны.",
		full = "Лунная поляна покоится в кольце гор — укрытая долина, где лес никогда не знал скверны. В её сердце лежит Озеро Элуне'ара, названное в честь самой богини, а в городе Ночная Гавань на его берегу таурены и ночные эльфы живут бок о бок без ссор, связанные общим благоговением перед природой, которое Стражи Лунной поляны не позволят нарушить.\n\nИменно в эту долину пришёл Малфурион Ярость Бури во времена Войны Древних, когда ночные эльфы стояли на краю гибели перед лицом Легиона. Малфурион знал, что его народ не сможет победить в одиночку, и привёл Тиранду Шелест Ветра и своего брата Иллидана в священную тишину Лунной поляны, чтобы умолить Кенария о помощи. Полубог откликнулся, и после того как Великий Раскол изменил облик мира, хранители рощи и дриады, укрывавшиеся здесь, отправились в этот мир. Сам же Кенарий так и не покинул поляну, и Лунная поляна стала самым святым местом поклонения друидов.\n\nПод её бесчисленными курганами спят святилища друидов былых времён, а под водами Элуне'ары тревожным сном спит полубог Омен, некогда возлюбленный Элуны.",
		source = "https://warcraft.wiki.gg/wiki/Moonglade",
	},
	[1451] = {
		name = "Силитус",
		short = "Эта пустыня лежит на крайнем юго-западе Калимдора — пустошь из битого камня и песка, куда ведёт широкая тропа из Ун'Горо.",
		full = "Эта пустыня лежит на крайнем юго-западе Калимдора — пустошь из битого камня и песка, куда ведёт широкая тропа из Ун'Горо. Под её поверхностью покоятся остатки империи акири, Ан'Кираж, центральный храм которой ночные эльфы запечатали, пытаясь не дать пробудиться чему-то ужасному. Руины, разбросанные по Силитусу, и ульи силитидов, ныне изрешетившие песок, — достаточное доказательство того, что печать не выдержала.\n\nДавным-давно самих киражей оттеснили за Стену Скарабея и заточили там после Войны Зыбучих песков. Их слуги, силитиды, остались на свободе и за века расплодились и распространились по всему южному Калимдору, пока ночные эльфы не сочли угрозу слишком великой, чтобы просто наблюдать за ней, и не решили вновь открыть Врата Ан'Киража, чтобы довершить то, что Стена лишь отсрочила.\n\nКруг Кенария несёт дозор из Крепости Кенария, следя за роями силитидов и решая, не слишком ли велика эта опасность, чтобы какой-либо народ мог противостоять ей в одиночку.",
		source = "https://warcraft.wiki.gg/wiki/Silithus_(Classic)",
	},
	[1452] = {
		name = "Зимние Ключи",
		short = "Нетронутый снег лежит по всем Зимним Ключам, и их красота не померкла даже там, где южные окраины захватили демоны. Когда-то здесь обитали многие синие драконы, и среди них Халех, супруга Малигоса.",
		full = "Нетронутый снег лежит по всем Зимним Ключам, и их красота не померкла даже там, где южные окраины захватили демоны. Когда-то здесь обитали многие синие драконы, и среди них Халех, супруга Малигоса.\n\nДесять тысяч лет назад высокорожденные воздвигли здесь город Кел'Терил, похитив Кристалл Зин-Малора из храма в Эльдарате. Они не смогли удержаться от того, чтобы испытать его силу, и когда кристалл раскололся, высвобожденное им проклятие поглотило их. Великий Раскол довершил начатое кристаллом, и Кел'Терил обратился в руины. Его мёртвые так и не ушли. Позднее из Кель'Таласа пришли высшие эльфы в поисках осколков кристалла, и то же безумие охватило и их. Теперь их призраки бродят по руинам рядом с теми, кого они пришли изучать.\n\nВ сердце долины гоблины удерживают Круговзор, а ночные эльфы по-прежнему несут здесь свой дозор, охраняя родину, более древнюю, чем они оба.",
		source = "https://warcraft.wiki.gg/wiki/Winterspring_(Classic)",
	},
	[1453] = {
		name = "Штормград",
		short = "Штормград восстал из белого камня после того, как его сожгла орочья Орда; отстроила его Гильдия каменщиков при юном короле Вариане.",
		full = "Штормград восстал из белого камня после того, как его сожгла орочья Орда; отстроила его Гильдия каменщиков при юном короле Вариане. Но когда казна короны иссякла из-за военных долгов, а знать отказалась платить гильдии, на протест главы гильдии Эдвина ван Клифа ответили её роспуском. Начались бунты, и в этой смуте погибла королева Тиффин Ринн. Гнев Вариана изгнал каменщиков в Западный Край, где они стали Братством Справедливости, — а за спиной у трона советница по имени Катрана Престор тем временем тихо настраивала короля против гильдии ради собственных целей.\n\nС тех пор король Вариан при подозрительных обстоятельствах пропал без вести, и по настоянию леди Престор корону передали его юному сыну, принцу Андуину, чтобы сохранить порядок в королевстве. Верховный лорд Болвар Фордрагон служит регентом Штормграда и командует его войсками, а леди Престор советует ему, как распоряжаться ресурсами королевства, не вызывая ни подозрений, ни возражений в стенах крепости.",
		source = "https://warcraft.wiki.gg/wiki/Stormwind_City",
	},
	[1454] = {
		name = "Оргриммар",
		short = "Оргриммар вырос в годы после битвы у горы Хиджал, когда вождь Тралл привёл свой народ на пустынное побережье Калимдора.",
		full = "Оргриммар вырос в годы после битвы у горы Хиджал, когда вождь Тралл привёл свой народ на пустынное побережье Калимдора. Он назвал эту землю Дуротаром в честь своего отца, а город, который он там воздвиг, назвал Оргриммаром в честь Оргрима Молота Рока — друга и наставника, сделавшего его тем, кем он стал. Город строили быстро, но не небрежно: крепкие стены, массивные ворота, высокие башни, а горы у него за спиной были вырублены так, что стали частью самой крепости, и сама земля встала на стражу города.\n\nОрда, что его построила, была уже не той Ордой, что некогда прошла по миру огнём. Когда демоническое проклятие было снято, народ Тралла обратился от завоеваний к выживанию, и Оргриммар возводили не только орки: рядом с ними трудились гоблины, таурены и тролли Черного Копья, а мок'натал Рексар тоже приложил руку к этой работе. Кентавры, гарпии, громоящеры, кобольды и свинобразы — все они испытывали юный город на прочность в первые годы, но он выстоял и стал домом не только для орков, но и для троллей, тауренов и со временем — для Отрекшихся, недавно принятых в Орду.\n\nДаже ветер здесь не друг: режущие ветра проносятся по долинам с такой силой, что срывают крыши с домов, построенных без должной заботы.",
		source = "https://warcraft.wiki.gg/wiki/Orgrimmar",
	},
	[1455] = {
		name = "Стальгорн",
		short = "Стальгорн — столица дворфов, высеченная в глубинах горы Стальгорн на севере Дун Морога, исконная родина дворфов и один из древнейших городов Азерота.",
		full = "Стальгорн — столица дворфов, высеченная в глубинах горы Стальгорн на севере Дун Морога, исконная родина дворфов и один из древнейших городов Азерота. Это столица Каз Модана, которой правит король Магни Бронзобород из клана Бронзобородов.\n\nОгромный подземный город ремесленников, исследователей, рудокопов и воинов, славящийся своим производством и как торговый центр Альянса, Стальгорн — в равной мере крепость и столица, свидетельство силы и стойкости дворфов. Город состоит из концентрических колец и уровней поменьше, уходящих глубже под землю, и все они расходятся от давшей ему имя Великой Кузни в его центре. Он полон узких проходов, лавок, встроенных прямо в каменные стены, и огромных залов. Здесь всё кипит, шумит и дышит ремеслом, и всё же уютно: в очагах таверн и лавок ревёт огонь, и повсюду слышны дворфский смех и веселье. В отличие от Штормграда и Дарнасса, этот город — огромная пещера, которую дворфы высекли в земле собственными руками; и потолок, и пол здесь из твёрдого камня.",
		source = "https://warcraft.wiki.gg/wiki/Ironforge",
	},
	[1456] = {
		name = "Громовой Утес",
		short = "Громовой Утес возвышается на четырёх продуваемых ветрами плато над лугами Мулгора, и попасть туда можно лишь на подъёмниках из верёвок и дерева, построенных тауренами, или по длинным мостам, перекинутым между вершинами.",
		full = "Громовой Утес возвышается на четырёх продуваемых ветрами плато над лугами Мулгора, и попасть туда можно лишь на подъёмниках из верёвок и дерева, построенных тауренами, или по длинным мостам, перекинутым между вершинами. Каждую вершину венчают шатры, длинные дома и расписные тотемы. Поколениями таурены скитались кочевым народом, и кентавры, рыскавшие по всему Калимдору, не давали им покоя. Положил конец этому изгнанию Кэрн Кровавое Копыто, вождь племени Кровавого Копыта. Когда во время Третьей войны вождь Тралл и его Новая Орда пришли в Мулгор, их сила соединилась с силой Кэрна, и вместе они разбили кентавров и наконец отвоевали луга для тауренов. На плато Кэрн воздвиг убежище, открытое для каждого рассеянного племени, и со временем эти племена как единый народ покорились его власти, порой расходясь во мнениях о дальнейшем пути, но никогда — в том, что он мудро ими правит.\n\nУтёсы до сих пор хранят память о том основании в своих вершинах и мостах, в шатрах племён, собравшихся под кровом одного вождя.",
		source = "https://warcraft.wiki.gg/wiki/Thunder_Bluff",
	},
	[1457] = {
		name = "Дарнасс",
		short = "Ночные эльфы построили Дарнасс после Третьей войны, когда их долгое бессмертие изменило им. Многие не смогли вынести внезапного бремени старения и немощи.",
		full = "Ночные эльфы построили Дарнасс после Третьей войны, когда их долгое бессмертие изменило им. Многие не смогли вынести внезапного бремени старения и немощи. Несколько скорбящих друидов решили вырастить новое Древо Жизни, чтобы восстановить свою связь с вечным миром. Поскольку Малфурион Ярость Бури пропал, Фэндрал Олений Шлем принял на себя звание верховного друида и возглавил это дело. Выращенное ими древо, Тельдрассил, поднялось у побережья, пока его крона не пронзила облака, и среди его ветвей ночные эльфы основали свой город в знак того, что их народ выжил.\n\nДарнасс открыт небу, в отличие от тесных, обнесённых стенами городов людей и дворфов. Он выстроен вокруг широкого озера, берега которого соединяют изящные мосты, а дорожки устланы опавшей листвой. Над деревьями возвышается Храм Луны — обитель верховной жрицы Тиранды Шелест Ветра и её Сестёр Элуны, а рядом стоит окружённый колоннадой Чертог Правосудия, где несут свою стражу Часовые. Город остаётся тем, ради чего его построили: тихим убежищем и памятником народу, который учится жить со своей смертностью.",
		source = "https://warcraft.wiki.gg/wiki/Darnassus",
	},
	[1458] = {
		name = "Подгород",
		short = "Задолго до того, как Отрекшиеся сделали его своим, Подгород имел имя и назначение. Глубоко под дворцом Лордерона тянулись древние склепы, где покоились его короли, а также темницы и сточные каналы.",
		full = "Задолго до того, как Отрекшиеся сделали его своим, Подгород имел имя и назначение. Глубоко под дворцом Лордерона тянулись древние склепы, где покоились его короли, а также темницы и сточные каналы. Предназначались они лишь для узников и мертвецов, но беднейшие жители Лордерона всё равно набивались во тьму, и облавы стражи, призванные их выгнать, так ни к чему и не привели.\n\nКогда власть Короля-лича над его созданиями ослабла, Сильвана Ветрокрылая откололась от Плети вместе с той нежитью, что сохранила разум, и обратилась против Артаса — падшего принца, сделавшего её тем, чем она стала. Она заманила его в ловушку в разорённом королевстве; он спасся с помощью Кел'Тузада и бежал на север, чтобы самому стать Королём-личом. Сильвана и её последователи, оставшиеся хозяевами поля боя, назвали себя Отрекшимися и заняли склепы под разрушенной столицей, достроив твердыню, начатую Плетью.\n\nТо, что стоит здесь ныне, — лабиринт, созданный для обороны: по каждой улице текут реки ядовитой слизи, а воздух полон испарений, которыми живые едва могут дышать. Для Отрекшихся это убежище в мире, который по-прежнему на них охотится.",
		source = "https://warcraft.wiki.gg/wiki/Undercity",
	},
}

